```js
condition && await test.step('my step', async () => {
  ...
});
```

will not show in reports. Visibility over what was run is one of the good characteristics of Playwright. If something was skipped, reports should reflect it.

My current workaround to support `test.step.skip` in both code and reporters:
```ts
// withStepSkip.ts
import { test as base, TestType } from '@playwright/test';

export const test = withStepSkip(base);

function withStepSkip<T extends TestType<any, any>>(test: T) {
  type Step = T['step'];
  const newTest = test as T & { step: Step & { skip: Step } };
  newTest.step.skip = ((...args: Parameters<Step>) => {
    return test.step(`[SKIPPED] ${args[0]}`, () => {}, { box: true });
  }) as Step;
  return newTest;
}
```
Usage:
```ts
import { test } from './withStepSkip';

test('test 1', async ({}) => {
  await test.step('Step 0', async () => {
    console.log('step 0');
  });
  await test.step.skip('Step 1', async () => {
    console.log('step 1');
  });
  await test.step('Step 2', async () => {
    console.log('step 2');
  });
});
```
